442	    /**
443	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
444	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
445	     * generated API signature, so it is read from the ambient request rather than a method parameter.
446	     */
447	    private static String currentIdempotencyKey() {
448	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
449	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
450	            return null;
451	        }
452	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
453	        return isBlank(key) ? null : key;
454	    }
