460	    /**
461	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
462	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
463	     * compared case-insensitively with collapsed whitespace.
464	     */
465	    private static String collapse(String value) {
466	        if (value == null) {
467	            return "";
468	        }
469	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
470	    }
471	
472	    /**
473	     * Common street-type abbreviations expanded during address normalization.
474	     */
475	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
476	        "ST", "STREET",
477	        "RD", "ROAD",
478	        "AVE", "AVENUE");
479	
480	    /**
481	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
482	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
483	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
484	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
485	     * address maps to itself.
486	     */
487	    private static String normalizeAddress(String value) {
488	        if (value == null) {
489	            return "";
490	        }
491	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
492	        if (collapsed.isEmpty()) {
493	            return "";
494	        }
495	        String[] tokens = collapsed.split(" ");
496	        StringBuilder sb = new StringBuilder(collapsed.length());
497	        for (int i = 0; i < tokens.length; i++) {
498	            if (i > 0) {
499	                sb.append(' ');
500	            }
501	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
502	        }
503	        return sb.toString();
504	    }
505	
506	    /**
507	     * Derive the stable household identifier shared by owners with the same normalized last name
508	     * and postcode. It is a deterministic function of those two values, so every member of a
509	     * household independently derives the same identifier: the first 12 upper-case hex characters
510	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
511	     * an empty segment.
512	     */
513	    private static String householdId(String normalizedLastName, String postcode) {
514	        try {
515	            byte[] digest = MessageDigest.getInstance("SHA-256")
516	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
517	                    .getBytes(StandardCharsets.UTF_8));
518	            StringBuilder sb = new StringBuilder(digest.length * 2);
519	            for (byte b : digest) {
520	                sb.append(String.format("%02x", b));
521	            }
522	            return sb.substring(0, 12).toUpperCase();
523	        }
524	        catch (NoSuchAlgorithmException e) {
525	            throw new IllegalStateException("SHA-256 not available", e);
526	        }
527	    }
528	
529	    /**
530	     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
531	     * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
532	     * null email or last name contributes an empty segment. Two owners are duplicates only when their
533	     * whole identity keys are equal. Delegates to {@link IdentityKeys#identityKey} so the value here
534	     * matches the one the mapper exposes on the owner DTO.
535	     */
536	    private static String identityKey(String telephone, String email, String lastName) {
537	        return IdentityKeys.identityKey(telephone, email, lastName);
538	    }
