540	    /**
541	     * Count the existing owners that share the given first and last name, compared
542	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
543	     * namesakes that already existed at creation time (the new owner itself is not included).
544	     */
545	    private int countNamesakes(String firstName, String lastName) {
546	        return (int) this.clinicService.findAllOwners().stream()
547	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
548	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
549	                && existing.getLastName().equalsIgnoreCase(lastName))
550	            .count();
551	    }
552	
553	    /**
554	     * Count the existing owners that already belong to the given household (i.e. carry the same
555	     * non-null householdId). Called after any existing members have been backfilled with the shared
556	     * identifier but before the new owner is saved, so the returned value reflects the members that
557	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
558	     * new owner is not part of any household ({@code householdId} is null).
559	     */
560	    private int countHouseholdMembers(String householdId) {
561	        if (householdId == null) {
562	            return 0;
563	        }
564	        return (int) this.clinicService.findAllOwners().stream()
565	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
566	            .count();
567	    }
568	
569	    /**
570	     * Compute the membership-level cap for a new owner joining the given household: one above the
571	     * current maximum membership level among the existing (non-deleted) members already carrying
572	     * this household id, using each member's effective (already-capped) level as returned to
573	     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
574	     */
575	    private Integer householdMembershipLevelCap(String householdId) {
576	        if (householdId == null) {
577	            return null;
578	        }
579	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
580	            .filter(existing -> !existing.isDeleted())
581	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
582	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
583	            .max();
584	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
585	    }
586	
587	    /**
588	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one whose
589	     * {@code soundex(lastName)} and postcode match the new owner's while its identity key differs (so
590	     * the two are not the same identity, which would already have been rejected as a 409). When
591	     * several existing owners match, the earliest (lowest id) is returned so the result is
592	     * deterministic. Returns {@code null} when there is no such owner — including when the new owner
593	     * has no last name or postcode, since a shared postcode is required to match.
594	     */
595	    private Owner findPossibleDuplicate(String lastName, String postcode, String identityKey) {
596	        if (isBlank(lastName) || isBlank(postcode)) {
597	            return null;
598	        }
599	        String soundex = IdentityKeys.soundex(lastName);
600	        return this.clinicService.findAllOwners().stream()
601	            .filter(existing -> !existing.isDeleted())
602	            .filter(existing -> soundex.equals(IdentityKeys.soundex(existing.getLastName())))
603	            .filter(existing -> postcode.equals(existing.getPostcode()))
604	            .filter(existing -> !identityKey.equals(
605	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
606	            .min(java.util.Comparator.comparing(Owner::getId))
607	            .orElse(null);
608	    }
