652	    /** Fixed public holidays the business-day roll skips. */
653	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
654	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
655	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
656	
657	    /**
658	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
659	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
660	     * business day is returned unchanged. Used so the effective registration date (whether supplied
661	     * or defaulted) always falls on a business day.
662	     */
663	    private static LocalDate toBusinessDay(LocalDate date) {
664	        while (isWeekendOrHoliday(date)) {
665	            date = date.plusDays(1);
666	        }
667	        return date;
668	    }
669	
670	    private static boolean isWeekendOrHoliday(LocalDate date) {
671	        return switch (date.getDayOfWeek()) {
672	            case SATURDAY, SUNDAY -> true;
673	            default -> PUBLIC_HOLIDAYS.contains(date);
674	        };
675	    }
