677	    /**
678	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
679	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
680	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
681	     */
682	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
683	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
684	    }
685	
686	    /**
687	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
688	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
689	     * {@code n} of 2 or more that produces a value no existing owner already carries.
690	     */
691	    private String deduplicateCustomerCode(String base) {
692	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
693	            .map(Owner::getCustomerCode)
694	            .filter(java.util.Objects::nonNull)
695	            .collect(java.util.stream.Collectors.toSet());
696	        if (!inUse.contains(base)) {
697	            return base;
698	        }
699	        int n = 2;
700	        while (inUse.contains(base + "-" + n)) {
701	            n++;
702	        }
703	        return base + "-" + n;
704	    }
705	
706	    /**
707	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
708	     */
709	    private static String hash8(String input) {
710	        try {
711	            byte[] digest = MessageDigest.getInstance("SHA-256")
712	                .digest(input.getBytes(StandardCharsets.UTF_8));
713	            StringBuilder sb = new StringBuilder(digest.length * 2);
714	            for (byte b : digest) {
715	                sb.append(String.format("%02x", b));
716	            }
717	            return sb.substring(0, 8).toUpperCase();
718	        }
719	        catch (NoSuchAlgorithmException e) {
720	            throw new IllegalStateException("SHA-256 not available", e);
721	        }
722	    }
723	
724	    /**
725	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
726	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
727	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
728	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
729	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
730	     * always agree.
731	     */
732	    private static String deriveRegion(String postcode, String city) {
733	        if (postcode != null && postcode.matches("\\d{4}")) {
734	            int value = Integer.parseInt(postcode);
735	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
736	                int[] range = entry.getValue();
737	                if (value >= range[0] && value <= range[1]) {
738	                    return entry.getKey();
739	                }
740	            }
741	        }
742	        if (city == null) {
743	            return "UNKNOWN";
744	        }
745	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
746	    }
747	
748	    /**
749	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
750	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
751	     * and accepts any 4-digit postcode.
752	     */
753	    private static final Map<String, String> CITY_REGION = Map.of(
754	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
755	
756	    /**
757	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
758	     * Each entry is a two-element {@code {low, high}} array.
759	     */
760	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
761	        "NSW", new int[] {2000, 2099},
762	        "VIC", new int[] {3000, 3099},
763	        "QLD", new int[] {4000, 4099});
764	
765	    /**
766	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
767	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
768	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
769	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
770	     * 4-digit postcode. A malformed or out-of-range postcode throws an
771	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
772	     */
773	    private static void validatePostcode(String city, String postcode) {
774	        if (postcode == null || postcode.isEmpty()) {
775	            return;
776	        }
777	        if (!postcode.matches("\\d{4}")) {
778	            throw new InvalidOwnerFieldsException(List.of("postcode"));
779	        }
780	        String region = city == null ? null : CITY_REGION.get(city);
781	        if (region == null) {
782	            return;
783	        }
784	        int[] range = REGION_POSTCODES.get(region);
785	        int value = Integer.parseInt(postcode);
786	        if (value < range[0] || value > range[1]) {
787	            throw new InvalidOwnerFieldsException(List.of("postcode"));
788	        }
789	    }
790	
791	    /**
792	     * Required national-number length for each E.164 country calling code we validate: a
793	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
794	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
795	     */
796	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
797	        "1", 10,
798	        "61", 9);
799	
800	    /**
801	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
802	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
803	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
804	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
805	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
806	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
807	     * rejected with a 400.
808	     */
809	    private static String toE164(String raw) {
810	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
811	        boolean hasCountryCode = cleaned.startsWith("+");
812	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
813	        if (!digits.matches("\\d+")) {
814	            throw new InvalidOwnerFieldsException(List.of("telephone"));
815	        }
816	        if (!hasCountryCode) {
817	            if (digits.startsWith("0")) {
818	                digits = digits.substring(1);
819	            }
820	            digits = "61" + digits;
821	        }
822	        if (digits.length() < 8 || digits.length() > 15) {
823	            throw new InvalidOwnerFieldsException(List.of("telephone"));
824	        }
825	        // For a recognised country code, the national number (the digits after the code) must be
826	        // exactly the expected length for that country. Match the longest known code so a shorter
827	        // code that is a prefix of another cannot mask it.
828	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
829	            if (digits.length() <= codeLength) {
830	                continue;
831	            }
832	            String countryCode = digits.substring(0, codeLength);
833	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
834	            if (requiredNationalLength != null) {
835	                if (digits.length() - codeLength != requiredNationalLength) {
836	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
837	                }
838	                break;
839	            }
840	        }
841	        return "+" + digits;
842	    }
843	
844	    /**
845	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
846	     * and a domain with at least one dot-separated label, none of which contain whitespace or
847	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
848	     */
849	    private static final Pattern EMAIL_PATTERN =
850	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
851	
852	    /**
853	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
854	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
855	     */
856	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
857	        "mailinator.com", "tempmail.com", "guerrillamail.com");
858	
859	    /**
860	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
861	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
862	     * domain is not on the disposable-domain blocklist, otherwise an
863	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
864	     * address is returned lower-cased.
865	     */
866	    private static String normalizeEmail(String email) {
867	        if (email == null || email.isEmpty()) {
868	            return null;
869	        }
870	        String trimmed = email.trim();
871	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
872	            throw new InvalidOwnerFieldsException(List.of("email"));
873	        }
874	        String normalized = trimmed.toLowerCase();
875	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
876	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
877	            throw new InvalidOwnerFieldsException(List.of("email"));
878	        }
879	        return normalized;
880	    }
881	}
